import{c as s,Q as n,j as t,m as p}from"./chunks/framework.DOi4mjdC.js";const e="/assets/zh-cn_formulaimage_0000002023909837.5WOapVbI.png",l="/assets/zh-cn_formulaimage_0000002023912661.C15QUcdx.png",o="/assets/SoftmaxFlashV2%E7%AE%97%E6%B3%95%E6%A1%86%E5%9B%BE.CpmIto0i.png",h=JSON.parse('{"title":"SoftmaxFlashV2","description":"","frontmatter":{},"headers":[{"level":1,"title":"SoftmaxFlashV2","slug":"softmaxflashv2"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"实现原理","slug":"实现原理"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxFlashV2.md","filePath":"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxFlashV2.md"}'),i={name:"api/SIMD-API/高阶API/激活函数/SoftMax接口/SoftmaxFlashV2.md"};function c(r,a,d,m,x,T){return n(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="softmaxflashv2" tabindex="-1">SoftmaxFlashV2 <a class="header-anchor" href="#softmaxflashv2" aria-label="Permalink to &quot;SoftmaxFlashV2&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>SoftmaxFlash增强版本，对应FlashAttention-2算法。将输入tensor[m0, m1, ...mt, n]（t大于等于0）的非尾轴长度相乘的结果看作m，则输入tensor的shape看作[m, n]。对输入tensor[m,n]按行做如下计算，不同的update值对应不同的计算公式，其中x、inmax和insum为输入，M、S、E均为输出。</p><ul><li><p>update为false：</p><p><img src="'+e+'" alt=""></p></li><li><p>update为true：</p><p><img src="'+l+`" alt=""></p></li></ul><p>当输入shape为ND格式时，内部的reduce过程按last轴进行；当输入shape为NZ格式时，内部的reduce过程按照last轴和first轴进行，reduce过程可以参考<a href="./SoftMax.html">SoftMax</a>中的图示说明。</p><p>为方便理解，通过Python脚本实现的方式，表达其计算公式如下，其中src、inmax、 insum、update为输入，dst、x_sum、x_max、exp_max为输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def softmax_flash_2(src, inmax=None, insum=None, update=None):</span></span>
<span class="line"><span>    if update is None:</span></span>
<span class="line"><span>        x_max = np.max(src, axis=-1, keepdims=True)</span></span>
<span class="line"><span>        x_sub = src - x_max   </span></span>
<span class="line"><span>        dst = np.exp(x_sub) </span></span>
<span class="line"><span>        x_sum = np.sum(dst, axis=-1, keepdims=True)</span></span>
<span class="line"><span>        exp_max = None</span></span>
<span class="line"><span>        return dst, x_max, x_sum, exp_max</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        x_max = np.max(np.concatenate((inmax, src), axis=-1), axis=-1, keepdims=True)</span></span>
<span class="line"><span>        dst = np.exp(src - x_max)</span></span>
<span class="line"><span>        exp_max = np.exp(inmax - x_max)</span></span>
<span class="line"><span>        x_sum = np.sum(dst, axis=-1, keepdims=True)</span></span>
<span class="line"><span>        x_sum = exp_max * insum +  x_sum</span></span>
<span class="line"><span>        return dst, x_max, x_sum, exp_max</span></span></code></pre></div><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><p>以float类型，ND格式，shape为[m, k]的输入Tensor为例，描述SoftmaxFlashV2高阶API内部算法框图，如下图所示。</p><p><strong>图 1</strong> SoftmaxFlashV2算法框图<br><img src="`+o+`" alt="" title="SoftmaxFlashV2算法框图"></p><p>计算过程根据isUpdate是否使能分为两个分支处理，均在Vector上进行。</p><ul><li><p>当isUpdate为False时，分为如下几步：</p><ol><li>reducemax步骤：对输入x的每一行数据求最大值得到[m, 1]，计算结果会保存到一个临时空间temp中；</li><li>broadcast步骤：对temp中的数据[m, 1]做一个按datablock为单位的填充，比如float类型下，把[m, 1]扩展成[m, 8]，同时输出max；</li><li>sub步骤：对输入x的所有数据按行减去max；</li><li>exp步骤：对sub之后的所有数据求exp，并且输出y；</li><li>reducesum步骤：对exp结果的每一行数据求和得到[m, 1]，计算结果会保存到临时空间temp中；</li><li>broadcast步骤：对temp[m, 1]做一个按datablock为单位的填充，比如float类型下，把[m, 1]扩展成[m, 8]，同时输出sum。</li></ol></li><li><p>当isUpdate为True时，分为如下几步：</p><ol><li>reducemax步骤：对输入x的每一行数据求最大值得到[m, 1]，计算结果会保存到一个临时空间temp中；</li><li>broadcast步骤：对temp中的数据[m, 1]做一个按datablock为单位的填充，比如float类型下，把[m, 1]扩展成[m, 8]，保存为max;</li><li>max步骤：对输入inmax和上一步计算的max做max操作，得到新的max并输出；</li><li>sub步骤：将输入inmax和新的max相减，然后做exp，计算得到expmax并输出；</li><li>sub步骤：将输入x和新的max按行相减；</li><li>exp步骤：对sub之后的所有数据求exp，并且输出y；</li><li>reducesum步骤：对exp结果的每一行数据求和得到[m, 1]，计算结果会保存到临时空间temp中；</li><li>broadcast步骤：对temp数据[m, 1]做一个按datablock为单位的填充，比如float类型下，把[m, 1]扩展成[m, 8]，保存到sum中；</li><li>mul步骤：将输入insum和expmax结果相乘；</li><li>add步骤：将相乘结果和sum相加，保存到sum并输出。</li></ol></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>接口框架申请临时空间</p><ul><li><p>LocalTensor的数据类型相同，不输出ReduceMax</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isUpdate = false, bool isReuseSource = false, bool isBasicBlock = false, bool isDataFormatNZ = false, const SoftmaxConfig&amp; config = SOFTMAX_DEFAULT_CFG&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxFlashV2(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; expSumTensor, const LocalTensor&lt;T&gt;&amp; maxTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;T&gt;&amp; expMaxTensor, const LocalTensor&lt;T&gt;&amp; inExpSumTensor, const LocalTensor&lt;T&gt;&amp; inMaxTensor, const SoftMaxTiling&amp; tiling, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div></li><li><p>LocalTensor的数据类型相同，且输出ReduceMax</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isUpdate = false, bool isReuseSource = false, bool isBasicBlock = false, bool isDataFormatNZ = false, const SoftmaxConfig&amp; config = SOFTMAX_DEFAULT_CFG&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxFlashV2(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; outReduceMax, const LocalTensor&lt;T&gt;&amp; outExpSum, const LocalTensor&lt;T&gt;&amp; outMax, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;T&gt;&amp; outExpMax, const LocalTensor&lt;T&gt;&amp; inExpSum, const LocalTensor&lt;T&gt;&amp; inMax, const SoftMaxTiling&amp; tiling, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div><p>Atlas 200I/500 A2 推理产品不支持该接口。</p><p>Atlas 推理系列产品AI Core不支持该接口。</p></li><li><p>LocalTensor的数据类型不同，不输出ReduceMax</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isUpdate = false, bool isReuseSource = false, bool isBasicBlock = false, bool isDataFormatNZ = false, const SoftmaxConfig&amp; config = SOFTMAX_DEFAULT_CFG&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxFlashV2(const LocalTensor&lt;half&gt;&amp; dstTensor, const LocalTensor&lt;float&gt;&amp; expSumTensor, const LocalTensor&lt;float&gt;&amp; maxTensor, const LocalTensor&lt;half&gt;&amp; srcTensor, const LocalTensor&lt;half&gt;&amp; expMaxTensor, const LocalTensor&lt;float&gt;&amp; inExpSumTensor, const LocalTensor&lt;float&gt;&amp; inMaxTensor, const SoftMaxTiling&amp; tiling, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div></li></ul></li><li><p>通过sharedTmpBuffer入参传入临时空间</p><ul><li><p>LocalTensor的数据类型相同，不输出ReduceMax</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isUpdate = false, bool isReuseSource = false, bool isBasicBlock = false, bool isDataFormatNZ = false, const SoftmaxConfig&amp; config = SOFTMAX_DEFAULT_CFG&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxFlashV2(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; outExpSum, const LocalTensor&lt;T&gt;&amp; outMax, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;T&gt;&amp; outExpMax, const LocalTensor&lt;T&gt;&amp; inExpSum, const LocalTensor&lt;T&gt;&amp; inMax, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const SoftMaxTiling&amp; tiling, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div></li><li><p>LocalTensor的数据类型相同，且输出ReduceMax</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isUpdate = false, bool isReuseSource = false, bool isBasicBlock = false, bool isDataFormatNZ = false, const SoftmaxConfig&amp; config = SOFTMAX_DEFAULT_CFG&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxFlashV2(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; outReduceMax, const LocalTensor&lt;T&gt;&amp; expSumTensor, const LocalTensor&lt;T&gt;&amp; maxTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;T&gt;&amp; expMaxTensor, const LocalTensor&lt;T&gt;&amp; inExpSumTensor, const LocalTensor&lt;T&gt;&amp; inMaxTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const SoftMaxTiling&amp; tiling, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div><p>Atlas 200I/500 A2 推理产品不支持该接口。</p><p>Atlas 推理系列产品AI Core不支持该接口。</p></li><li><p>LocalTensor的数据类型不同，不输出ReduceMax</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isUpdate = false, bool isReuseSource = false, bool isBasicBlock = false, bool isDataFormatNZ = false, const SoftmaxConfig&amp; config = SOFTMAX_DEFAULT_CFG&gt;</span></span>
<span class="line"><span>__aicore__ inline void SoftmaxFlashV2(const LocalTensor&lt;half&gt;&amp; dstTensor, const LocalTensor&lt;float&gt;&amp; expSumTensor, const LocalTensor&lt;float&gt;&amp; maxTensor, const LocalTensor&lt;half&gt;&amp; srcTensor, const LocalTensor&lt;half&gt;&amp; expMaxTensor, const LocalTensor&lt;float&gt;&amp; inExpSumTensor, const LocalTensor&lt;float&gt;&amp; inMaxTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const SoftMaxTiling&amp; tiling, const SoftMaxShapeInfo&amp; softmaxShapeInfo = {})</span></span></code></pre></div></li></ul></li></ul><p>由于该接口的内部实现中涉及复杂的计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式。</p><ul><li><p>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</p></li><li><p>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li></ul><p>接口框架申请的方式，开发者需要预留临时空间；通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间。临时空间大小BufferSize的获取方式如下：通过<a href="./SoftmaxFlashV2-Tiling接口.html">SoftmaxFlashV2 Tiling接口</a>中提供的GetSoftMaxFlashV2MinTmpSize/GetSoftMaxFlashV2MaxTmpSize接口获取所需最小和最大临时空间大小，最小空间可以保证功能正确，最大空间用于提升性能。</p><p>另外提供了一个kernel侧tiling计算的接口，当kernel侧的输入shape与通过host侧TilingData传入的shape不一致时，可使用该接口在kernel侧重新计算tiling。该接口的参数含义请参考<a href="./SoftmaxFlashV2-Tiling接口.html">SoftmaxFlashV2 Tiling接口</a>。</p><ul><li><p><strong>kernel侧tiling计算接口</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline constexpr SoftMaxTiling SoftMaxFlashV2TilingFunc(const SoftMaxShapeInfo&amp; shapeInfo, const uint32_t dataTypeSize1, const uint32_t dataTypeSize2, const uint32_t localWorkSpaceSize, const bool isUpdate = false, const bool isBasicBlock = false, const bool isDataFormatNZ = false, const bool isFlashOutputBrc = false)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>isUpdate</td><td>是否使能update部分中的计算。</td></tr><tr><td>isReuseSource</td><td>该参数预留，传入默认值false即可。</td></tr><tr><td>isBasicBlock</td><td>srcTensor和dstTensor的shape信息和Tiling切分策略满足基本块要求的情况下，可以使能该参数用于提升性能，默认不使能。是否满足基本块的要求，可以采用如下两种方式之一判断： srcTensor和dstTensor的shape信息[m,n]需要满足如下条件：尾轴长度n小于2048并且大于等于256/sizeof(T)（即half场景下n最小为128，float场景下n最小为64），同时n是64的倍数；非尾轴长度的乘积m为8的倍数。 在Tiling实现中，通过调用IsBasicBlockInSoftMax判断Tiling切分策略是否满足基本块的切分要求。 针对Atlas 200I/500 A2 推理产品，该参数为预留参数，暂未启用，为后续的功能扩展做保留，保持默认值即可。</td></tr><tr><td>isDataFormatNZ</td><td>当前输入输出的数据格式是否为NZ格式，默认数据格式为ND，即默认取值为false。 针对Atlas 200I/500 A2 推理产品，不支持配置为NZ格式。</td></tr><tr><td>config</td><td>结构体模板参数，此参数可选配，SoftmaxConfig类型，具体定义如下方代码所示，其中参数的含义为： isCheckTiling：是否需要检查shape和tiling的一致性；若不一致，API内会根据shape重新计算所需tiling。默认取值true：API内部会检查一致性。oriSrcM：原始非尾轴长度的乘积。设置该参数后，将shape常量化，编译过程中使用常量化的shape。oriSrcK：原始尾轴长度。设置该参数后，将shape常量化，编译过程中使用常量化的shape。mode：输出shape的处理模式。当输入输出的数据格式为NZ格式时，不支持配置mode参数。SoftmaxMode类型，取值如下：SOFTMAX_NORMAL ：默认值，常规模式，对输出数据做Broadcast，使得输出shape由(m, 1)拓展成(m, 8)（输出为float数据类型）或者(m, 16)（输出为half数据类型）。SOFTMAX_OUTPUT_WITHOUT_BRC ：非拓展模式，不对输出数据做Broadcast，输出shape均为(m, 1)，相应的输入参数（例如inExpSumTensor、inMaxTensor），shape也均为(m, 1) 。 此参数一般用于配合kernel侧tiling计算的接口使用。 注意：设置了oriSrcM与oriSrcK后，模板参数isBasicBlock不生效，计算数据是否为基本块由API内部判断并处理。 针对Ascend 950PR/Ascend 950DT，支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持该参数。 针对Atlas 200I/500 A2 推理产品，该参数为预留参数，暂未启用，保持默认值即可。 Atlas 推理系列产品AI Core，支持该参数，不支持配置mode。 针对Kirin X90，支持该参数。 针对Kirin 9030，支持该参数。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct SoftmaxConfig{</span></span>
<span class="line"><span>    bool isCheckTiling = true; </span></span>
<span class="line"><span>    uint32_t oriSrcM = 0;</span></span>
<span class="line"><span>    uint32_t oriSrcK = 0;</span></span>
<span class="line"><span>    SoftmaxMode mode = SoftmaxMode::SOFTMAX_NORMAL;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>配置示例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr SoftmaxConfig SOFTMAX_DEFAULT_CFG = {true, 0, 0, SoftmaxMode::SOFTMAX_NORMAL};</span></span></code></pre></div><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstTensor</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 dstTensor的shape和源操作数srcTensor一致。</td></tr><tr><td>outReduceMax</td><td>输出</td><td>目的操作数。用于保存softmax计算过程中reducemax第一次计算的结果。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 outReduceMax的shape与目的操作数maxTensor一致。 对于输出该结果的接口： 模板参数isUpdate为false时，不输出该结果。仅支持输入输出的数据格式为ND，模板参数isDataFormatNZ为预留参数，传入默认值false即可。模板参数config.isCheckTiling为预留参数，传入默认值false即可。模板参数config.mode仅支持配置为非拓展模式SoftmaxMode::SOFTMAX_OUTPUT_WITHOUT_BRC。</td></tr><tr><td>expSumTensor、outExpSum</td><td>输出</td><td>目的操作数。用于保存softmax计算过程中reducesum的结果。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 除模板参数config配置为非拓展模式（SoftmaxMode::SOFTMAX_OUTPUT_WITHOUT_BRC）的场景外，expSumTensor的last轴长度固定为32Byte，即一个datablock长度。该datablock中的所有数据为同一个值，比如half数据类型下，该datablock中的16个数均为相同的reducesum的值。非last轴的长度与dstTensor保持一致。</td></tr><tr><td>maxTensor、outMax</td><td>输出</td><td>目的操作数。用于保存softmax计算过程中reducemax的结果。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 除模板参数config配置为非拓展模式（SoftmaxMode::SOFTMAX_OUTPUT_WITHOUT_BRC）的场景外，maxTensor的last轴长度固定为32Byte，即一个datablock长度。该datablock中的所有数据为同一个值。比如half数据类型下，该datablock中的16个数均为相同的reducemax的值。非last轴的长度与dstTensor保持一致。</td></tr><tr><td>srcTensor</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 last轴长度需要32Byte对齐。</td></tr><tr><td>expMaxTensor、outExpMax</td><td>输出</td><td>目的操作数。用于保存inmax与reducemax差值的e的指数幂的结果。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 除模板参数config配置为非拓展模式（SoftmaxMode::SOFTMAX_OUTPUT_WITHOUT_BRC）的场景外，expMaxTensor的last轴长度固定为32Byte，即一个datablock长度。该datablock中的所有数据为同一个值，比如half数据类型下，该datablock中的16个数均为相同的值。非last轴的长度需要与dstTensor保持一致。</td></tr><tr><td>inExpSumTensor、inExpSum</td><td>输入</td><td>源操作数。softmax计算所需要的sum值。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 除模板参数config配置为非拓展模式（SoftmaxMode::SOFTMAX_OUTPUT_WITHOUT_BRC）的场景外，inExpSumTensor的last轴长度固定为32Byte，即一个datablock长度。该datablock中的所有数据为同一个值，比如half数据类型下，该datablock中的16个数均为相同的值。非last轴的长度需要与dstTensor保持一致。</td></tr><tr><td>inMaxTensor、inMax</td><td>输入</td><td>源操作数。softmax计算所需要的max值。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 除模板参数config配置为非拓展模式（SoftmaxMode::SOFTMAX_OUTPUT_WITHOUT_BRC）的场景外，inMaxTensor的last轴长度固定为32Byte，即一个datablock长度。该datablock中的所有数据为同一个值，比如half数据类型下，该datablock里的16个数均为相同的值。非last轴的长度需要与dstTensor保持一致。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时空间。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 该操作数的数据类型固定uint8_t。 接口内部复杂计算时用于存储中间变量，由开发者提供。 临时空间大小BufferSize的获取方式请参考SoftmaxFlashV2 Tiling接口。</td></tr><tr><td>tiling</td><td>输入</td><td>softmaxflashv2接口计算所需tiling信息，Tiling信息的获取请参考SoftmaxFlashV2 Tiling接口。</td></tr><tr><td>softmaxShapeInfo</td><td>输入</td><td>srcTensor的shape信息。SoftMaxShapeInfo类型，具体定义如下方代码所示，其中参数的含义为： srcM：非尾轴长度的乘积。srcK：尾轴长度，必须32Byte对齐oriSrcM：原始非尾轴长度的乘积。oriSrcK：原始尾轴长度。 需要注意，当输入输出的数据格式为NZ格式时，尾轴长度为reduce轴长度即图2中的W0<em>W1，非尾轴为H0</em>H1。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct SoftMaxShapeInfo {</span></span>
<span class="line"><span>  uint32_t srcM; </span></span>
<span class="line"><span>  uint32_t srcK; </span></span>
<span class="line"><span>  uint32_t oriSrcM;  </span></span>
<span class="line"><span>  uint32_t oriSrcK;  </span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>srcTensor和dstTensor的Tensor的空间可以复用，maxTensor和inMaxTensor的空间可以复用，expSumTensor和inExpSumTensor的空间可以复用。</p></li><li><p>除模板参数config配置为非拓展模式（SoftmaxMode::SOFTMAX_OUTPUT_WITHOUT_BRC）的场景外，expSumTensor、maxTensor、expMaxTensor、inExpSumTensor、inMaxTensor的Tensor空间，last轴长度必须固定32Byte。</p></li><li><p>对于输出ReduceMax的接口：</p><ul><li>模板参数isReuseSource、isDataFormatNZ、config.isCheckTiling均为预留参数；</li><li>config.mode只支持配置为非拓展模式SOFTMAX_OUTPUT_WITHOUT_BRC，其配置为SOFTMAX_NORMAL模式时，接口功能不执行，不保存各输出；</li><li>模板参数isUpdate为false时，outReduceMax不输出；</li><li>除outReduceMax外，其余每个输出的计算结果与<a href="#section620mcpsimp">不输出ReduceMax的接口</a>相同。</li></ul></li><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。</p></li><li><p>当参数softmaxShapeInfo中srcM != oriSrcM 或者 srcK != oriSrcK时，开发者需要对GM上的原始输入(oriSrcM, oriSrcK)在M或K方向补齐数据到(srcM, srcK)，补齐的数据会参与部分运算，在输入输出复用的场景下，API的计算结果会覆盖srcTensor中补齐的原始数据，在输入输出不复用的场景下，API的计算结果会覆盖dstTensor中对应srcTensor补齐位置的数据。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>srcK对齐</p><p>本样例中输入srcTensor和输出dstTensor的shape大小为[320,64]，输入inSumTensor、inMaxTensor的shape大小为[320,16]，输出expMaxTensor的shape大小为[320,16]，数据类型均为half，输入输出的数据排布格式为ND，srcTensor和dstTensor空间不复用，不使能基本块，isUpdate为true。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal: 存放SoftMax计算结果的Tensor</span></span>
<span class="line"><span>// expSumLocal：存放softmax计算过程中reducesum的结果</span></span>
<span class="line"><span>// maxLocal：存放softmax计算过程中reducemax的结果</span></span>
<span class="line"><span>// srcLocal：存放SoftMax计算的输入Tensor</span></span>
<span class="line"><span>// expMaxLocal：存放inmax与reducemax差值的e的指数幂的结果</span></span>
<span class="line"><span>// inExpSumLocal：存放softmax计算所需要的sum值</span></span>
<span class="line"><span>// inMaxLocal：存放softmax计算所需要的max值</span></span>
<span class="line"><span>// sharedTmpBuffer: 存放SoftMax计算过程中临时缓存的Tensor</span></span>
<span class="line"><span>// softmaxTiling：存放SoftMax计算所需Tiling信息，可通过SoftMaxFlashV2TilingFunc接口获取</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::SoftMaxShapeInfo softmaxInfo(</span></span>
<span class="line"><span>    /* 非尾轴长度的乘积          */ 320, </span></span>
<span class="line"><span>    /* 尾轴长度，必须32Bytes对齐 */ 64, </span></span>
<span class="line"><span>    /* 原始非尾轴长度的乘积      */ 320, </span></span>
<span class="line"><span>    /* 原始尾轴长度              */ 64</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 通过sharedTmpBuffer入参传入临时空间，不输出ReduceMax，传入模板参数将shape常量化</span></span>
<span class="line"><span>AscendC::SoftmaxFlashV2&lt;T, true, false, false, false, static_config&gt;(dstLocal, expSumLocal, maxLocal, srcLocal, expMaxLocal, inExpSumLocal, inMaxLocal, sharedTmpBuffer, tiling, softmaxInfo);</span></span>
<span class="line"><span>// 通过sharedTmpBuffer入参传入临时空间，不输出ReduceMax</span></span>
<span class="line"><span>AscendC::SoftmaxFlashV2&lt;T, true&gt;(dstLocal, expSumLocal, maxLocal, srcLocal, expMaxLocal, inExpSumLocal, inMaxLocal, sharedTmpBuffer, tiling, softmaxInfo);</span></span>
<span class="line"><span>// 接口框架申请临时空间，带sumTensor和maxTensor参数</span></span>
<span class="line"><span>AscendC::SoftmaxFlashV2&lt;T, true&gt;(dstLocal, expSumLocal, maxLocal, srcLocal, expMaxLocal, inExpSumLocal, inMaxLocal, tiling, softmaxInfo);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcLocal)：</span></span>
<span class="line"><span>[[-10.    -10.    -10.    ...  -9.94   -9.94   -9.94 ]</span></span>
<span class="line"><span> [ -9.94   -9.94   -9.94  ...  -9.875  -9.875  -9.875]</span></span>
<span class="line"><span> [ -9.875  -9.875  -9.875 ...  -9.81   -9.81   -9.81 ]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [  9.81    9.81    9.81  ...   9.875   9.875   9.875]</span></span>
<span class="line"><span> [  9.875   9.875   9.875 ...   9.94    9.94    9.94 ]</span></span>
<span class="line"><span> [  9.94    9.94    9.94  ...  10.     10.     10.   ]]</span></span>
<span class="line"><span>输出数据(expSumLocal)：</span></span>
<span class="line"><span>[[62.03 62.03 62.03 ... 62.03 62.03 62.03]</span></span>
<span class="line"><span> [62.03 62.03 62.03 ... 62.03 62.03 62.03]</span></span>
<span class="line"><span> [62.03 62.03 62.03 ... 62.03 62.03 62.03]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [62.03 62.03 62.03 ... 62.03 62.03 62.03]</span></span>
<span class="line"><span> [62.03 62.03 62.03 ... 62.03 62.03 62.03]</span></span>
<span class="line"><span> [62.03 62.03 62.03 ... 62.03 62.03 62.03]]</span></span>
<span class="line"><span>输出数据(maxLocal)：</span></span>
<span class="line"><span>[[-9.94  -9.94  -9.94  ... -9.94  -9.94  -9.94 ]</span></span>
<span class="line"><span> [-9.875 -9.875 -9.875 ... -9.875 -9.875 -9.875]</span></span>
<span class="line"><span> [-9.81  -9.81  -9.81  ... -9.81  -9.81  -9.81 ]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [ 9.875  9.875  9.875 ...  9.875  9.875  9.875]</span></span>
<span class="line"><span> [ 9.94   9.94   9.94  ...  9.94   9.94   9.94 ]</span></span>
<span class="line"><span> [10.    10.    10.    ... 10.    10.    10.   ]]</span></span>
<span class="line"><span>输出数据(dstLocal)：</span></span>
<span class="line"><span>[[0.015144 0.015144 0.015144 ... 0.01611  0.01611  0.01611 ]</span></span>
<span class="line"><span> [0.015144 0.015144 0.015144 ... 0.01611  0.01611  0.01611 ]</span></span>
<span class="line"><span> [0.015144 0.015144 0.015144 ... 0.01611  0.01611  0.01611 ]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [0.015144 0.015144 0.015144 ... 0.01611  0.01611  0.01611 ]</span></span>
<span class="line"><span> [0.015144 0.015144 0.015144 ... 0.01611  0.01611  0.01611 ]</span></span>
<span class="line"><span> [0.015144 0.015144 0.015144 ... 0.01611  0.01611  0.01611 ]]</span></span></code></pre></div></li><li><p>srcK非对齐</p><p>本示例中srcTensor和输出dstTensor的shape大小为[320,63]，数据类型均为half，输入输出的数据排布格式为ND，展示非对齐padding补齐的搬入搬出操作和API调用方式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;kernel_operator.h&quot;</span></span>
<span class="line"><span>// init阶段  height=320, width=63</span></span>
<span class="line"><span>padWidth = AlignUp(width * sizeof(T), 32) / sizeof(T);</span></span>
<span class="line"><span>// copyin阶段</span></span>
<span class="line"><span>AscendC::DataCopyExtParams copyParams{static_cast&lt;uint16_t&gt;(height), static_cast&lt;uint32_t&gt;(width * sizeof(T)), 0, 0, 0};</span></span>
<span class="line"><span>AscendC::DataCopyPadExtParams&lt;T&gt; padParam = {true, 0, static_cast&lt;uint8_t&gt;(padWidth - width), 0};</span></span>
<span class="line"><span>AscendC::DataCopyPad(srcLocal, srcGlobal, copyParams, padParam);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// compute阶段</span></span>
<span class="line"><span>// 由于发生padding，API调用时shape和原始shape发生了不一致</span></span>
<span class="line"><span>AscendC::SoftMaxShapeInfo srcShape = {height, padWidth, height, width};</span></span>
<span class="line"><span>AscendC::SoftmaxFlashV2&lt;T, true&gt;(dstLocal, expSumLocal, maxLocal, srcLocal, expMaxLocal, inExpSumLocal, inMaxLocal, tiling, srcShape);</span></span>
<span class="line"><span>// copyout阶段</span></span>
<span class="line"><span>AscendC::DataCopyExtParams copyParams{static_cast&lt;uint16_t&gt;(height), static_cast&lt;uint32_t&gt;(width * sizeof(T)), 0, 0, 0};</span></span>
<span class="line"><span>AscendC::DataCopyPad(dstGlobal, dstLocal, copyParams);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcLocal)：</span></span>
<span class="line"><span>[[-10.    -10.    -10.    ...  -9.94   -9.94    0.   ]</span></span>
<span class="line"><span> [ -9.94   -9.94   -9.94  ...  -9.875  -9.875   0.   ]</span></span>
<span class="line"><span> [ -9.875  -9.875  -9.875 ...  -9.81   -9.81    0.   ]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [  9.81    9.81    9.81  ...   9.875   9.875   0.   ]</span></span>
<span class="line"><span> [  9.875   9.875   9.875 ...   9.94    9.94    0.   ]</span></span>
<span class="line"><span> [  9.94    9.94    9.94  ...  10.     10.      0.   ]]</span></span>
<span class="line"><span>输出数据(expSumLocal)：</span></span>
<span class="line"><span>[[61.03 61.03 61.03 ... 61.03 61.03 61.03]</span></span>
<span class="line"><span> [61.03 61.03 61.03 ... 61.03 61.03 61.03]</span></span>
<span class="line"><span> [61.03 61.03 61.03 ... 61.03 61.03 61.03]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [61.1  61.1  61.1  ... 61.1  61.1  61.1 ]</span></span>
<span class="line"><span> [61.1  61.1  61.1  ... 61.1  61.1  61.1 ]</span></span>
<span class="line"><span> [61.1  61.1  61.1  ... 61.1  61.1  61.1 ]]</span></span>
<span class="line"><span>输出数据(maxLocal)：</span></span>
<span class="line"><span>[[-9.94  -9.94  -9.94  ... -9.94  -9.94  -9.94 ]</span></span>
<span class="line"><span> [-9.875 -9.875 -9.875 ... -9.875 -9.875 -9.875]</span></span>
<span class="line"><span> [-9.81  -9.81  -9.81  ... -9.81  -9.81  -9.81 ]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [ 9.875  9.875  9.875 ...  9.875  9.875  9.875]</span></span>
<span class="line"><span> [ 9.94   9.94   9.94  ...  9.94   9.94   9.94 ]</span></span>
<span class="line"><span> [10.    10.    10.    ... 10.    10.    10.   ]]</span></span>
<span class="line"><span>输出数据(dstLocal)：</span></span>
<span class="line"><span>[[0.015396 0.015396 0.015396 ... 0.01639  0.01639  0.01639 ]</span></span>
<span class="line"><span> [0.015396 0.015396 0.015396 ... 0.01639  0.01639  0.01639 ]</span></span>
<span class="line"><span> [0.015396 0.015396 0.015396 ... 0.01639  0.01639  0.01639 ]</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> [0.01538  0.01538  0.01538  ... 0.01637  0.01637  0.01637 ]</span></span>
<span class="line"><span> [0.01538  0.01538  0.01538  ... 0.01637  0.01637  0.01637 ]</span></span>
<span class="line"><span> [0.01538  0.01538  0.01538  ... 0.01637  0.01637  0.01637 ]]</span></span></code></pre></div></li></ul>`,36)])])}const f=s(i,[["render",c]]);export{h as __pageData,f as default};
